export const LEVELS = [
 {name:'第一次回响',subtitle:'THE FIRST ECHO',brief:'一道门，两个自己。改变过去，从留下第一个回声开始。',duration:45,spawn:{x:-7,z:4},plates:[{id:'A',x:-5,z:-3}],walls:[{x:0,requires:['A']}],cubes:[],lasers:[],exit:{x:6.5,z:-2.8},shards:[{x:-6,z:-4.7},{x:3,z:3.5},{x:6.5,z:-4.7}],hints:['走到 A 压力板上，让它亮起。','站在 A 上按 R。过去的你会重播行动，并留在终点。','等回声压住 A，穿过中间的门，走到反应堆旁按 E。'],story:'事故发生前 45 秒，你回到了赫利俄斯实验室。你只有一个盟友：曾经的自己。'},
 {name:'重量与回声',subtitle:'WEIGHT OF THE PAST',brief:'回声也有重量。让一段记忆和一个方块，为你打开前路。',duration:55,spawn:{x:-7,z:4},plates:[{id:'A',x:-5,z:-3},{id:'B',x:-2,z:3}],walls:[{x:2,requires:['A','B']}],cubes:[{x:-6,z:1.5}],lasers:[{x:4,phase:0}],exit:{x:7,z:-2.8},shards:[{x:-7,z:-4.8},{x:-1,z:-4},{x:6,z:4.5}],hints:['先走到 B 并按 R，让过去的自己留在这里。','按 E 拿起能量方块，搬到 A 上再按 E 放下。回溯会重置方块。','A、B 同时亮起后穿门。等激光熄灭再通过，空格可减缓时间。'],story:'记录显示，安全门并没有损坏。那一刻，只是没有足够的人同时留在控制位。'},
 {name:'三次约定',subtitle:'A PROMISE ACROSS TIME',brief:'四个位置，一次共同抵达。把未来交给每一个过去的自己。',duration:70,spawn:{x:-7.5,z:4},plates:[{id:'A',x:-6,z:-3},{id:'B',x:.8,z:3.7},{id:'C',x:4,z:-3.8},{id:'D',x:4,z:3.3}],walls:[{x:-3,requires:['A']},{x:2,requires:['A','B']},{x:6,requires:['A','B','C','D']}],cubes:[{x:-6.5,z:4.8}],lasers:[{x:0,phase:1.8}],exit:{x:7.6,z:-2.5},shards:[{x:-7.3,z:-4.8},{x:0,z:-4.5},{x:4,z:5}],hints:['先在 A 留下第一个回声。每道门都需要之前的站位保持激活。','第二轮穿过第一道门，在 B 留下第二个回声；第三轮到 C 留下第三个。','最后一轮把起点的方块搬到 D。四个位置同时亮起后，去反应堆按 E。'],story:'这一次，没有人必须独自留下。你与三个过去的自己，终于拥有改变结局的机会。'}
];
const dist=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
export class TimeEngine {
 constructor(level=0){this.load(level);}
 load(index){this.levelIndex=index;this.level=LEVELS[index];this.echoes=[];this.rewinds=0;this.failures=0;this.collected=new Set();this.events=[];this.won=false;this.resetLoop();}
 resetLoop(){this.time=0;this.energy=5;this.player={...this.level.spawn,angle:0};this.cubes=this.level.cubes.map(c=>({...c}));this.carrying=-1;this.trace=[{t:0,...this.player}];this.echoPositions=this.echoes.map(()=>({...this.level.spawn}));this.active={};this.path=[];this.updatePlates();}
 event(type,text){this.events.push({type,text});}
 rewind(save=true){if(this.won)return false;if(save){if(this.echoes.length>=3){this.event('notice','回声已满：撤销最近回声后，可以重新录制。');return false;}if(this.time<.35){this.event('notice','先移动到你想留下回声的位置。');return false;}this.trace.push({t:this.time,...this.player});this.echoes.push({frames:this.trace.map(f=>({...f})),duration:this.time});this.rewinds++;}this.resetLoop();this.event('rewind',save?'时间已回溯。过去的你，将重播这段行动。':'本轮重新开始，已有回声仍然保留。');return true;}
 undo(){if(!this.echoes.length){this.event('notice','还没有可以撤销的回声。');return;}this.echoes.pop();this.resetLoop();this.event('rewind','最近的回声已撤销。重新录制你的计划。');}
 echoAt(e,t){const f=e.frames;if(t>=e.duration)return {...f[f.length-1]};let lo=0,hi=f.length-1;while(lo<hi-1){let m=(lo+hi)>>1;if(f[m].t<=t)lo=m;else hi=m;}const a=f[lo],b=f[hi],p=Math.min(1,(t-a.t)/Math.max(.001,b.t-a.t));return {x:a.x+(b.x-a.x)*p,z:a.z+(b.z-a.z)*p,angle:a.angle+(b.angle-a.angle)*p};}
 updatePlates(){for(const p of this.level.plates)this.active[p.id]=[this.player,...this.echoPositions,...this.cubes.filter((_,i)=>i!==this.carrying)].some(a=>dist(a,p)<.79);}
 gateOpen(w){return w.requires.every(id=>this.active[id])||(Math.abs(this.player.x-w.x)<.58&&Math.abs(this.player.z)<.95);}
 unobstructed(a,b){for(let j=1;j<12;j++){const f=j/12;if(this.isSolid(a.x+(b.x-a.x)*f,a.z+(b.z-a.z)*f,.05))return false;}return true;}
 isSolid(x,z,r=.3){if(x<-8.5+r||x>8.5-r||z<-5.9+r||z>5.9-r)return true;for(const w of this.level.walls){if(Math.abs(x-w.x)<.28+r&&(Math.abs(z)>1.25-r||!this.gateOpen(w)))return true;}return false;}
 laserActive(l){return (this.time+l.phase)%6<3.4;}
 update(dt,input={}){if(this.won)return;dt=Math.min(dt,.05);const focus=input.focus&&this.energy>0;const worldDt=dt*(focus?.25:1);if(focus)this.energy=Math.max(0,this.energy-dt);this.time+=worldDt;this.echoPositions=this.echoes.map(e=>this.echoAt(e,this.time));this.updatePlates();let dx=input.x||0,dz=input.z||0;if(Math.hypot(dx,dz)>0)this.path=[];else if(this.path.length){const p=this.path[0],d=dist(this.player,p);if(d<.15)this.path.shift();else{dx=(p.x-this.player.x)/d;dz=(p.z-this.player.z)/d;}}const mag=Math.hypot(dx,dz);if(mag){dx/=mag;dz/=mag;const speed=(input.sprint?4.8:3.3)*(this.carrying>=0?.8:1);const nx=this.player.x+dx*dt*speed,nz=this.player.z+dz*dt*speed;if(!this.isSolid(nx,this.player.z))this.player.x=nx;if(!this.isSolid(this.player.x,nz))this.player.z=nz;this.player.angle=Math.atan2(dx,dz);}
 if(this.carrying>=0){this.cubes[this.carrying]={x:this.player.x,z:this.player.z};}
 this.updatePlates();if(this.time-this.trace[this.trace.length-1].t>=.04)this.trace.push({t:this.time,...this.player});
 this.level.shards.forEach((s,i)=>{if(!this.collected.has(i)&&dist(this.player,s)<.65){this.collected.add(i);this.event('shard',['记忆 01：实验室事故，从来不是命中注定。','记忆 02：过去无法被抹去，但它可以成为你的盟友。','记忆 03：每一次选择，都在未来留下回响。'][i]);}});
 for(const l of this.level.lasers)if(this.laserActive(l)&&Math.abs(this.player.x-l.x)<.2){this.failures++;this.rewind(false);this.event('hazard','触碰了激光。已安全回退，等光束熄灭再穿过。');return;}
 if(this.time>=this.level.duration){this.failures++;this.rewind(false);this.event('hazard','事故窗口关闭。已回到起点，过去的回声仍然保留。');}
 }
 interaction(){if(this.carrying>=0)return '放下能量方块';if(dist(this.player,this.level.exit)<1.45)return '稳定反应堆';if(this.cubes.some(c=>dist(this.player,c)<1.35&&this.unobstructed(this.player,c)))return '拿起能量方块';return null;}
 interact(){if(this.won)return; if(this.carrying>=0){let target=null;const plate=this.level.plates.find(p=>dist(this.player,p)<1.05&&!this.isSolid(p.x,p.z,.3));if(plate)target=plate;else{for(const d of [.8,.55,0]){const p={x:this.player.x+Math.sin(this.player.angle)*d,z:this.player.z+Math.cos(this.player.angle)*d};if(!this.isSolid(p.x,p.z,.3)){target=p;break;}}}if(!target){this.event('notice','这里无法放下方块。');return;}this.cubes[this.carrying]={x:target.x,z:target.z};this.carrying=-1;this.updatePlates();this.event('interact','能量方块已放下。');return;}
 if(dist(this.player,this.level.exit)<1.45){if(this.level.plates.every(p=>this.active[p.id])){this.won=true;this.event('win','反应堆已稳定。你改变了这一次的结局。');}else this.event('notice','所有压力板同时激活时，才能稳定反应堆。');return;}
 const i=this.cubes.findIndex(c=>dist(this.player,c)<1.35&&this.unobstructed(this.player,c));if(i>=0){this.carrying=i;this.event('interact','已拿起方块。靠近压力板后按 E 放下。');}else this.event('notice','靠近能量方块或反应堆，然后按 E。');}
 navigate(x,z){const step=.45;const key=(a,b)=>a+','+b;const sx=Math.round(this.player.x/step),sz=Math.round(this.player.z/step),tx=Math.round(x/step),tz=Math.round(z/step);if(this.isSolid(tx*step,tz*step))return false;const open=[{x:sx,z:sz,g:0,f:0}],seen=new Map(),closed=new Set();seen.set(key(sx,sz),open[0]);let end=null;for(let n=0;open.length&&n<2200;n++){open.sort((a,b)=>a.f-b.f);const a=open.shift(),k=key(a.x,a.z);if(closed.has(k))continue;closed.add(k);if(a.x===tx&&a.z===tz){end=a;break;}for(const [dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=a.x+dx,nz=a.z+dz,nk=key(nx,nz);if(closed.has(nk)||this.isSolid(nx*step,nz*step,.34))continue;const g=a.g+1;if(!seen.has(nk)||seen.get(nk).g>g){const b={x:nx,z:nz,g,f:g+Math.abs(tx-nx)+Math.abs(tz-nz),prev:a};seen.set(nk,b);open.push(b);}}}if(!end)return false;const path=[];while(end.prev){path.unshift({x:end.x*step,z:end.z*step});end=end.prev;}path.push({x,z});this.path=path;return true;}
 state(){return {level:this.levelIndex+1,time:Number(this.time.toFixed(2)),duration:this.level.duration,player:{...this.player},echoes:this.echoes.length,active:{...this.active},shards:this.collected.size,carrying:this.carrying>=0,won:this.won};}
}
